public record KitActionPayload(String action,String kitId,String json,long requestId) implements CustomPacketPayload{public static final Type<KitActionPayload> TYPE=new Type<>(ResourceLocation.fromNamespaceAndPath(SimpleServerUtilities.MODID,"kit_action"));public static final StreamCodec<RegistryFriendlyByteBuf,KitActionPayload> STREAM_CODEC=StreamCodec.of(KitActionPayload::encode,KitActionPayload::decode);public KitActionPayload{action=PayloadBounds.string(action,32);kitId=PayloadBounds.string(kitId,64);json=PayloadBounds.string(json,32767);requestId=Math.max(0L,requestId);}private static void encode(RegistryFriendlyByteBuf b,KitActionPayload p){b.writeUtf(p.action,32);b.writeUtf(p.kitId,64);b.writeUtf(p.json,32767);b.writeVarLong(p.requestId);}private static KitActionPayload decode(RegistryFriendlyByteBuf b){return new KitActionPayload(b.readUtf(32),b.readUtf(64),b.readUtf(32767),b.readVarLong());}@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}}
